// ============================================================
//  Rage of the Mage — 2D sprite sheets
// ============================================================
// Each sheet is 128x32: four 32x32 pixel-art frames, drawn facing right.
// Units facing left are mirrored at draw time. Sheets are generated by
// tools/make-sprites.py (no runtime dependency).

export const SPRITE_NAMES = [
  "warrior",
  "mage",
  "ranger",
  "skeleton",
  "zombie",
  "wight",
  "necromancer",
];

export const FRAME_COUNT = 4;
export const FRAME_SIZE = 32;

const DIR = "assets/sprites";
const images = {};
let loaded = 0;

const ALLY_SPRITE = {
  belgarath: "mage",
  polgara: "mage",
  durnik: "warrior",
  silk: "ranger",
  barak: "warrior",
};

export function preloadSprites() {
  if (Object.keys(images).length) return;
  for (const name of SPRITE_NAMES) {
    const img = new Image();
    img.decoding = "async";
    img.src = `${DIR}/${name}.png`;
    img.addEventListener("load", () => { loaded += 1; });
    images[name] = img;
  }
}

export function spritesReady() {
  return loaded === SPRITE_NAMES.length;
}

export function spriteKey(unit) {
  if (!unit) return "warrior";
  if (unit.sprite && images[unit.sprite]) return unit.sprite;
  if (unit.side === "enemy") {
    return images[unit.kind] ? unit.kind : "skeleton";
  }
  if (unit.kind && ALLY_SPRITE[unit.kind]) return ALLY_SPRITE[unit.kind];
  return SPRITE_NAMES.includes(unit.cls) ? unit.cls : "warrior";
}

export function spriteImage(unit) {
  const key = spriteKey(unit);
  const img = images[key];
  return img && img.complete && img.naturalWidth ? img : null;
}
